let libs = ['data/libs/serial.js']

let myShader
let matcap, obj
let matcap1, obj1
let gltf

var serial;
var portName = '/dev/cu.usbmodem141401';

// Camera properties
let camera;


// Variables to store raw sensor values
var joy = {x:512, y:512};
var accel = {x:0, y:0, z:0};
var gyro  = {x:0, y:0, z:0};
var temp  = 0;

// Variables to store smoothed sensor values
var smoothedJoy = {x:512, y:512};
var smoothedGyro = {x:0, y:0, z:0};
var smoothedAccel = {x:0, y:0, z:0};

// Smoothing factor (0.0 to 1.0). Lower values are smoother.
var smoothing = 0.01;



function preload() {
  matcap = loadImage("includes/demos-data/images/fish.png")
  obj = loadModel("includes/demos-data/3d/teapot.obj")
  matcap1 = loadImage("data/images/imagen3.png")
  obj1 = loadModel("data/obj/algorave1.obj")
  //gltf = loadModel("data/GLTF/scene.gltf")
}

function setup() {


  createCanvas(windowWidth, windowHeight, WEBGL);
  camera = createCamera();
  pixelDensity(1)
  noStroke()
  myShader = createShader(vertShader, fragShader);

  serial = new p5.SerialPort();
  serial.open(portName);

  // When serial data arrives, call parseData
  serial.on('data', parseData);
}

function draw() {
  background(0)
  shader(myShader)

  //	// Map smoothed sensor values for rotation and size
  //let rotX = map(smoothedGyro.x, -17000, 17000, -PI, PI);
  //let rotY = map(smoothedGyro.y, -17000, 17000, -PI, PI);
  //let rotZ = map(smoothedGyro.z, -17000, 17000, -PI, PI);

  //// Use smoothed accelerometer values to rotate the cube
  //rotateX(rotX);
  //rotateY(rotZ);
  //rotateZ(rotY);
  //orbitControl(5)
	updateContols();
  // --- First model ---
  push()
    myShader.setUniform("uMatcapTexture", matcap)
    // rotateX(radians(frameCount / 2))
    // rotateZ(radians(frameCount / 4))
    translate(-150, 0, 0)
    scale(5)
    model(obj)
  pop()

  // --- Second model ---
  push()
    myShader.setUniform("uMatcapTexture", matcap1)
    // rotateX(radians(frameCount / 2))
    // rotateZ(radians(frameCount / 4))
    translate(150, 0, 0)
