// update controls

// Parse incoming CSV text from Arduino
function parseData() {
  let inString = serial.readLine(); // Read one line
  //console.log(inString);
  if (!inString) return;             // Ignore empty lines

  // Split by commas
  let values = inString.split(',');
  if (values.length < 9) return;    // Ensure all fields are present

  // Convert strings to numbers and update raw sensor values
  joy.x   = int(values[0]);
  joy.y   = int(values[1]);

  accel.x = int(values[2]);
  accel.y = int(values[3]);
  accel.z = int(values[4]);

  gyro.x  = int(values[5]);
  gyro.y  = int(values[6]);
  gyro.z  = int(values[7]);

  temp    = float(values[8]);
}

let updateContols = () => {

	// Smooth the sensor values using linear interpolation (lerp)
	  smoothedJoy.x = lerp(smoothedJoy.x, joy.x, smoothing);
	  smoothedJoy.y = lerp(smoothedJoy.y, joy.y, smoothing);
	  smoothedGyro.x = lerp(smoothedGyro.x, gyro.x, smoothing);
	  smoothedGyro.y = lerp(smoothedGyro.y, gyro.y, smoothing);
	  smoothedGyro.z = lerp(smoothedGyro.z, gyro.z, smoothing);
	  smoothedAccel.x = lerp(smoothedAccel.x, accel.x, smoothing);
	  smoothedAccel.y = lerp(smoothedAccel.y, accel.y, smoothing);
	  smoothedAccel.z = lerp(smoothedAccel.z, accel.z, smoothing);

};

/* SHADER DEFINITIONS */
let vertShader = `
  attribute vec3 aPosition;
  attribute vec2 aTexCoord;
  attribute vec3 aNormal;

  uniform mat4 uProjectionMatrix;
  uniform mat4 uModelViewMatrix;
  uniform mat4 uNormalMatrix;

  varying vec3 vNormal;
  varying vec3 vEye;

  void main() {
    vEye = normalize(vec3(uModelViewMatrix * vec4(aPosition, 1.0)));
    vNormal = normalize((uModelViewMatrix * vec4(aNormal, 0.0)).xyz);
    vec4 positionVec4 = vec4(aPosition, 1.0);
    gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
  }
`

let fragShader = `
  precision mediump float;

  varying vec3 vNormal;
  varying vec3 vEye;

  uniform sampler2D uMatcapTexture;

  vec2 matcap(vec3 eye, vec3 normal) {
    vec3 reflected = reflect(eye, normal);
    float m = 2.8284271247461903 * sqrt(reflected.z + 1.0);
    return reflected.xy / m + 0.5;
  }

  void main() {
    vec2 uv = matcap(vEye, vNormal);
    vec4 color = texture2D(uMatcapTexture, uv);
    gl_FragColor = color;
  }
`
